CREATE TABLE IF NOT EXISTS email_preferences (user_id VARCHAR(40) PRIMARY KEY, training_enabled INTEGER NOT NULL DEFAULT 1, marketing_enabled INTEGER NOT NULL DEFAULT 0, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS email_campaigns (id VARCHAR(40) PRIMARY KEY, course_id VARCHAR(40), kind VARCHAR(30) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL, author_id VARCHAR(40) NOT NULL, recipients INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS email_outbox (id VARCHAR(40) PRIMARY KEY, dedupe_key VARCHAR(190) NOT NULL UNIQUE, user_id VARCHAR(40) NOT NULL, campaign_id VARCHAR(40), course_id VARCHAR(40), resource_id VARCHAR(40), kind VARCHAR(30) NOT NULL, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, link_path VARCHAR(240) NOT NULL, status VARCHAR(20) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error_code VARCHAR(80), message_id VARCHAR(180), lock_token VARCHAR(40), locked_until VARCHAR(30), next_attempt_at VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(campaign_id) REFERENCES email_campaigns(id));
CREATE INDEX IF NOT EXISTS idx_email_due ON email_outbox(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_email_user ON email_outbox(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_email_campaign ON email_outbox(campaign_id,status);
CREATE TABLE IF NOT EXISTS email_attempts (id VARCHAR(40) PRIMARY KEY, message_id VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(message_id) REFERENCES email_outbox(id));
CREATE INDEX IF NOT EXISTS idx_email_attempt_time ON email_attempts(created_at);
